1	package tariff
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// 替代版本登记回归保障所用的固定时间线（全部为 UTC 零点，结束时刻不含）：
10	//
11	//	旧版本 seat-v1：单价 150 分，2026-03-01 起，登记结束 2026-03-31
12	//	新版本 seat-v2：单价 180 分，拟从 2026-03-10 起替代 seat-v1
13	//	后续版本 seat-v3：单价 200 分，2026-04-01 起持续有效，与 v1 没有替代关系
14	//
15	// v2 的交接点本身合法（落在 v1 当前有效区间内），Replaces 只能截短 v1，
16	// 不能让 v2 占用同项其他版本 v3 的有效时间。所有时刻在代码中写死并注入固定时钟，
17	// 结论不依赖运行当天的真实日期或时间流逝。
18	var (
19		rrOldStart    = time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)
20		rrOldEnd      = time.Date(2026, 3, 31, 0, 0, 0, 0, time.UTC)
21		rrHandoff     = time.Date(2026, 3, 10, 0, 0, 0, 0, time.UTC)
22		rrFollowStart = time.Date(2026, 4, 1, 0, 0, 0, 0, time.UTC)
23	)
24	
25	// newReplacementBaseBook 准备只登记了 v1、v3 两个版本的账本：
26	// v1 为 3 月内有效的旧版本，v3 从 4 月 1 日起持续有效，二者无替代关系。
27	func newReplacementBaseBook(t *testing.T) *Book {
28		t.Helper()
29		now, _ := fixedClock(rrOldStart)
30		b := NewBook(WithClock(now))
31		oldEnd := rrOldEnd
32		if err := b.RegisterVersion(RegisterRequest{
33			ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150,
34			Start: rrOldStart, End: &oldEnd,
35		}); err != nil {
36			t.Fatalf("register seat-v1: %v", err)
37		}
38		if err := b.RegisterVersion(RegisterRequest{
39			ItemID: "seat", VersionID: "seat-v3", UnitPrice: 200,
40			Start: rrFollowStart,
41		}); err != nil {
42			t.Fatalf("register seat-v3: %v", err)
43		}
44		return b
45	}
46	
47	// assertReplacementBaseUnchanged 校验失败登记整次回滚：
48	// 查询仍只有 v1、v3，v1 未被提前截断、没有失败版本留下的替代关系，
49	// v3 继续保持原来的持续有效区间。
50	func assertReplacementBaseUnchanged(t *testing.T, b *Book) {
51		t.Helper()
52		views, err := b.ItemVersions("seat")
53		if err != nil {
54			t.Fatal(err)
55		}
56		if len(views) != 2 {
57			t.Fatalf("失败登记后应仍只有两个版本，got %d: %+v", len(views), views)
58		}
59		old, follow := views[0], views[1]
60		if old.VersionID != "seat-v1" || follow.VersionID != "seat-v3" {
61			t.Fatalf("失败登记后版本集合/顺序异常: %q, %q", old.VersionID, follow.VersionID)
62		}
63	
64		// 旧版本：登记结束与实际有效结束都仍是 3 月 31 日，不能止于 3 月 10 日。
65		if old.UnitPrice != 150 {
66			t.Fatalf("旧版本单价被改写: %d", old.UnitPrice)
67		}
68		if old.End == nil || !old.End.Equal(rrOldEnd) {
69			t.Fatalf("旧版本登记结束被改写: %v", old.End)
70		}
71		if old.EffectiveEnd == nil || !old.EffectiveEnd.Equal(rrOldEnd) {
72			t.Fatalf("旧版本不能被失败登记提前截断，实际结束应仍为 3 月 31 日, got %v", old.EffectiveEnd)
73		}
74		if old.Replaces != "" || old.SupersededBy != "" {
75			t.Fatalf("失败登记不能留下替代关系: Replaces=%q SupersededBy=%q",
76				old.Replaces, old.SupersededBy)
77		}
78	
79		// 后续版本：从 4 月 1 日起持续有效，无替代关系。
80		if follow.UnitPrice != 200 {
81			t.Fatalf("后续版本单价被改写: %d", follow.UnitPrice)
82		}
83		if !follow.Start.Equal(rrFollowStart) {
84			t.Fatalf("后续版本开始时刻被改写: %v", follow.Start)
85		}
86		if follow.End != nil || follow.EffectiveEnd != nil {
87			t.Fatalf("后续版本应仍持续有效: 登记结束=%v 实际结束=%v",
88				follow.End, follow.EffectiveEnd)
89		}
90		if follow.Replaces != "" || follow.SupersededBy != "" {
91			t.Fatalf("后续版本替代关系应保持为空: Replaces=%q SupersededBy=%q",
92				follow.Replaces, follow.SupersededBy)
93		}
94	}
95	
96	// 即使交接点合法，替代版本也不能占用同项另一个已登记版本的有效时间：
97	// 不填结束时间会延伸进持续有效的 v3；结束时间只要晚于 4 月 1 日零点，
98	// 哪怕只超出一纳秒，或已经通过 Replaces 指定了被替代版本，仍必须返回 ErrOverlap。
99	func TestReplacementOverlapsFollowUpVersion(t *testing.T) {
100		cases := []struct {
101			name string
102			end  *time.Time
103		}{
104			{"不填结束时间-持续有效", nil},
105			{"结束晚于后续版本开始一纳秒", timePtr(rrFollowStart.Add(time.Nanosecond))},
106			{"结束晚于后续版本开始一分钟", timePtr(rrFollowStart.Add(time.Minute))},
107			{"结束晚于后续版本开始一整天", timePtr(rrFollowStart.Add(24 * time.Hour))},
108		}
109		for _, c := range cases {
110			t.Run(c.name, func(t *testing.T) {
111				b := newReplacementBaseBook(t)
112	
113				err := b.RegisterVersion(RegisterRequest{
114					ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
115					Start: rrHandoff, End: c.end, Replaces: "seat-v1",
116				})
117				if !errors.Is(err, ErrOverlap) {
118					t.Fatalf("替代版本占用后续版本有效时间应返回 ErrOverlap, got %v", err)
119				}
120	
121				// 失败不留痕迹：原两版不变，失败版本及其标识都不在查询结果中。
122				assertReplacementBaseUnchanged(t, b)
123			})
124		}
125	}
126	
127	// 结束时间恰好等于后续版本的开始时刻属于端点相接（结束时刻不含），不算重叠。
128	func TestReplacementEndingExactlyAtFollowUpStartAllowed(t *testing.T) {
129		b := newReplacementBaseBook(t)
130		end := rrFollowStart
131		if err := b.RegisterVersion(RegisterRequest{
132			ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
133			Start: rrHandoff, End: &end, Replaces: "seat-v1",
134		}); err != nil {
135			t.Fatalf("与后续版本端点相接的替代登记应成功: %v", err)
136		}
137	
138		views, err := b.ItemVersions("seat")
139		if err != nil {
140			t.Fatal(err)
141		}
142		if len(views) != 3 {
143			t.Fatalf("want 3 versions, got %d", len(views))
144		}
145		got := []string{views[0].VersionID, views[1].VersionID, views[2].VersionID}
146		want := []string{"seat-v1", "seat-v2", "seat-v3"}
147		for i := range want {
148			if got[i] != want[i] {
149				t.Fatalf("版本应按生效时刻排列为 %v, got %v", want, got)
150			}
151		}
152	}
153	
154	// 完整回归：替代登记先因重叠被拒，用户修正结束时间后沿用同一版本标识成功；
155	// 成功后三个版本的登记边界、实际有效区间与替代关系逐一符合预期。
156	// 整段流程在全新账本上重复执行多轮，保证结论稳定可复现。
157	func TestReplacementRejectedThenSucceedsWithSameVersionID(t *testing.T) {
158		const rounds = 3
159		for round := 0; round < rounds; round++ {
160			t.Run("重复登记失败再修正", func(t *testing.T) {
161				b := newReplacementBaseBook(t)
162	
163				// 第一次尝试：不填结束时间，延伸进 v3 的有效时间，被拒。
164				err := b.RegisterVersion(RegisterRequest{
165					ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
166					Start: rrHandoff, Replaces: "seat-v1",
167				})
168				if !errors.Is(err, ErrOverlap) {
169					t.Fatalf("第%d轮: 无结束时间的替代登记应返回 ErrOverlap, got %v", round+1, err)
170				}
171				assertReplacementBaseUnchanged(t, b)
172	
173				// 修正结束时间为 4 月 1 日零点（不含），沿用原标识与其余登记内容。
174				fixedEnd := rrFollowStart
175				if err := b.RegisterVersion(RegisterRequest{
176					ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
177					Start: rrHandoff, End: &fixedEnd, Replaces: "seat-v1",
178				}); err != nil {
179					t.Fatalf("第%d轮: 失败登记不应占用版本标识，修正后沿用原标识应成功, got %v",
180						round+1, err)
181				}
182	
183				views, err := b.ItemVersions("seat")
184				if err != nil {
185					t.Fatal(err)
186				}
187				if len(views) != 3 {
188					t.Fatalf("第%d轮: 成功后应有三个版本, got %d", round+1, len(views))
189				}
190				old, nv, follow := views[0], views[1], views[2]
191				if old.VersionID != "seat-v1" || nv.VersionID != "seat-v2" ||
192					follow.VersionID != "seat-v3" {
193					t.Fatalf("第%d轮: 版本集合/顺序异常: %q, %q, %q",
194						round+1, old.VersionID, nv.VersionID, follow.VersionID)
195				}
196	
197				// 旧版本：登记结束仍是 3 月 31 日（永不因后续登记改变），
198				// 实际有效结束被截断到 3 月 10 日，并显示由 v2 替代。
199				if old.UnitPrice != 150 || !old.Start.Equal(rrOldStart) {
200					t.Fatalf("第%d轮: 旧版本登记信息异常: %+v", round+1, old)
201				}
202				if old.End == nil || !old.End.Equal(rrOldEnd) {
203					t.Fatalf("第%d轮: 旧版本登记结束应仍为 3 月 31 日, got %v", round+1, old.End)
204				}
205				if old.EffectiveEnd == nil || !old.EffectiveEnd.Equal(rrHandoff) {
206					t.Fatalf("第%d轮: 旧版本实际有效结束应为交接点 3 月 10 日, got %v",
207						round+1, old.EffectiveEnd)
208				}
209				if old.Replaces != "" || old.SupersededBy != "seat-v2" {
210					t.Fatalf("第%d轮: 旧版本替代关系异常: Replaces=%q SupersededBy=%q",
211						round+1, old.Replaces, old.SupersededBy)
212				}
213	
214				// 新版本：实际有效区间为 [3 月 10 日, 4 月 1 日)，替代 v1。
215				if nv.UnitPrice != 180 {
216					t.Fatalf("第%d轮: 新版本单价应为 180, got %d", round+1, nv.UnitPrice)
217				}
218				if !nv.Start.Equal(rrHandoff) || !nv.EffectiveStart.Equal(rrHandoff) {
219					t.Fatalf("第%d轮: 新版本开始时刻应为 3 月 10 日: %+v", round+1, nv)
220				}
221				if nv.End == nil || !nv.End.Equal(rrFollowStart) ||
222					nv.EffectiveEnd == nil || !nv.EffectiveEnd.Equal(rrFollowStart) {
223					t.Fatalf("第%d轮: 新版本有效区间应为 [03-10, 04-01): 登记结束=%v 实际结束=%v",
224						round+1, nv.End, nv.EffectiveEnd)
225				}
226				if nv.Replaces != "seat-v1" || nv.SupersededBy != "" {
227					t.Fatalf("第%d轮: 新版本替代关系异常: Replaces=%q SupersededBy=%q",
228						round+1, nv.Replaces, nv.SupersededBy)
229				}
230	
231				// 后续版本：边界与替代关系保持登记时的原值。
232				if follow.UnitPrice != 200 || !follow.Start.Equal(rrFollowStart) {
233					t.Fatalf("第%d轮: 后续版本登记信息异常: %+v", round+1, follow)
234				}
235				if follow.End != nil || follow.EffectiveEnd != nil {
236					t.Fatalf("第%d轮: 后续版本应仍持续有效: 登记结束=%v 实际结束=%v",
237						round+1, follow.End, follow.EffectiveEnd)
238				}
239				if follow.Replaces != "" || follow.SupersededBy != "" {
240					t.Fatalf("第%d轮: 后续版本不应出现替代关系: Replaces=%q SupersededBy=%q",
241						round+1, follow.Replaces, follow.SupersededBy)
242				}
243			})
244		}
245	}
246	
247	// timePtr 返回时间的指针，供表驱动用例填写结束时刻。
248	func timePtr(t time.Time) *time.Time {
249		return &t
250	}
